export function startReconcile(db: Db, port: PaypalPort): void {
  let busy = false
  const tick = async (): Promise<void> => {
    if (busy) return
    busy = true
    try {
      for (const row of all(db, 'SELECT DISTINCT paypal_order_id FROM captures')) {
        const orderId = String(row.paypal_order_id)
        const ledger = await port.getOrder(orderId)
        for (const r of ledger.refunds) {
          if (r.status === 'COMPLETED') run(db, 'INSERT OR IGNORE INTO refunds (paypal_refund_id, paypal_order_id, amount) VALUES (?, ?, ?)', r.id, orderId, r.amount)
        }
      }
    } catch {
      // try again on the next tick
    } finally {
      busy = false
    }
  }
  setInterval(() => void tick(), 1000).unref()
}
